#include <stdio.h>

/* Two heaps: low is a max-heap holding the smaller half,
   high is a min-heap holding the larger half. */
int low[128], lowN = 0;
int high[128], highN = 0;

void lowPush(int x) {
    int i = lowN++;
    low[i] = x;
    while (i > 0 && low[(i - 1) / 2] < low[i]) {
        int t = low[i];
        low[i] = low[(i - 1) / 2];
        low[(i - 1) / 2] = t;
        i = (i - 1) / 2;
    }
}

int lowPop(void) {
    int top = low[0];
    low[0] = low[--lowN];
    int i = 0;
    while (1) {
        int l = 2 * i + 1, r = 2 * i + 2, b = i;
        if (l < lowN && low[l] > low[b]) b = l;
        if (r < lowN && low[r] > low[b]) b = r;
        if (b == i) break;
        int t = low[i];
        low[i] = low[b];
        low[b] = t;
        i = b;
    }
    return top;
}

void highPush(int x) {
    int i = highN++;
    high[i] = x;
    while (i > 0 && high[(i - 1) / 2] > high[i]) {
        int t = high[i];
        high[i] = high[(i - 1) / 2];
        high[(i - 1) / 2] = t;
        i = (i - 1) / 2;
    }
}

int highPop(void) {
    int top = high[0];
    high[0] = high[--highN];
    int i = 0;
    while (1) {
        int l = 2 * i + 1, r = 2 * i + 2, b = i;
        if (l < highN && high[l] < high[b]) b = l;
        if (r < highN && high[r] < high[b]) b = r;
        if (b == i) break;
        int t = high[i];
        high[i] = high[b];
        high[b] = t;
        i = b;
    }
    return top;
}

void addNum(int n) {
    lowPush(n);
    highPush(lowPop());
    if (lowN < highN) lowPush(highPop());
}

double median(void) {
    return lowN > highN ? low[0] : (low[0] + high[0]) / 2.0;
}

int main() {
    int stream[] = {5, 15, 1, 3};
    for (int i = 0; i < 4; i++) {
        addNum(stream[i]);
        printf("after %d median = %.1f\n", stream[i], median());
    }
    return 0;
}

